import '@servicenow/sdk/global'
import { Flow, trigger, wfa, action } from '@servicenow/sdk/automation'
import { StringColumn, IntegerColumn, BooleanColumn, DateTimeColumn } from '@servicenow/sdk/core'

/**
 * SetFlowVariables with Datapills Example
 * Demonstrates: Using wfa.dataPill() with setFlowVariables
 */
Flow(
    {
        $id: Now.ID['set_flow_variables_datapills_example'],
        name: 'SetFlowVariables with Datapills Example',
        description: 'Demonstrates using datapills with setFlowVariables',
        runAs: 'system',
        flowVariables: {
            userName: StringColumn({
                label: 'User Name',
                mandatory: true,
            }),
            incidentNumber: StringColumn({
                label: 'Incident Number',
                mandatory: true,
            }),
            priority: IntegerColumn({
                label: 'Priority',
                mandatory: true,
            }),
            isActive: BooleanColumn({
                label: 'Is Active',
                mandatory: true,
            }),
            timestamp: DateTimeColumn({
                label: 'Timestamp',
                mandatory: true,
            }),
            recordId: StringColumn({
                label: 'Record ID',
                mandatory: true,
            }),
            message: StringColumn({
                label: 'Message',
                mandatory: true,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['set_flow_vars_trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_setting: 'both',
            run_when_user_list: [],
            run_when_user_setting: 'any',
        }
    ),
    (_params) => {
        // Example 1: setFlowVariables with trigger datapills
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set_vars_from_trigger'],
                annotation: 'Set flow variables from trigger datapills',
            },
            _params.flowVariables,
            {
                userName: wfa.dataPill(_params.trigger.current.sys_created_by, 'string'),
                incidentNumber: wfa.dataPill(_params.trigger.current.number, 'string'),
                priority: wfa.dataPill(_params.trigger.current.priority, 'integer'),
                timestamp: wfa.dataPill(_params.trigger.current.sys_created_on, 'string'),
                isActive: true,
            }
        )

        // Create a record to get action outputs
        const createAction = wfa.action(
            action.core.createRecord,
            {
                $id: Now.ID['create_record_for_vars'],
            },
            {
                table_name: 'task',
                values: `short_description: "${wfa.dataPill(_params.flowVariables.userName, 'string')}"`,
            }
        )

        // Example 2: setFlowVariables with action output datapills
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set_vars_from_action'],
                annotation: 'Set flow variables from action output datapills',
            },
            _params.flowVariables,
            {
                recordId: wfa.dataPill(createAction.record, 'reference'),
            }
        )

        // Example 3: setFlowVariables with flow variable datapills
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set_vars_from_flow_vars'],
                annotation: 'Set flow variables from other flow variable datapills',
            },
            _params.flowVariables,
            {
                message: `User ${wfa.dataPill(_params.flowVariables.userName, 'string')} created incident ${wfa.dataPill(_params.flowVariables.incidentNumber, 'string')}`,
            }
        )

        // Example 4: setFlowVariables with mixed datapills and literals
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set_vars_mixed'],
                annotation: 'Set flow variables with mixed datapills and literals',
            },
            _params.flowVariables,
            {
                priority: 1,
                isActive: wfa.dataPill(_params.flowVariables.isActive, 'boolean'),
                message: `Priority updated for ${wfa.dataPill(_params.flowVariables.incidentNumber, 'string')}`,
            }
        )

        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_set_vars_completion'],
            },
            {
                log_level: 'info',
                log_message: wfa.dataPill(_params.flowVariables.message, 'string'),
            }
        )
    }
)
